function cannyEdgeDetection()
    % Prompt the user to select an input image file
    inputImage = uigetfile({'*.jpg;*.png;*.bmp', 'Image Files'}, 'Select an Image File');
    if isequal(inputImage, 0)
        return;
    end

    % Read the image
    img = imread(inputImage);

    % Convert to grayscale if it's not already
    if size(img, 3) == 3
        img = rgb2gray(img);
    end

    % Display the original image
    figure;
    imshow(img);
    title('Original Image');

    % Display histogram of grayscale pixel values
    figure;
    hist = imhist(img);
    bar(0:255, hist);
    title('Histogram of Grayscale Pixel Values');
    xlabel('Pixel Value');
    ylabel('Frequency');

    % Prompt the user to choose a threshold value based on the histogram
    threshold = input('Enter a threshold value (0-255): ');

    % Prompt the user to select a smoothing filter
    filterChoice = input('Choose a smoothing filter (1: Gaussian, 2: Median): ');

    % Apply smoothing filter if selected
    if filterChoice == 1
        img = imgaussfilt(img, 2); % Gaussian filter with sigma = 2
    elseif filterChoice == 2
        img = medfilt2(img, [3 3]); % Median filter with 3x3 window
    end
